// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (who attempts to change owner) and newOwner target
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid the zero address for clarity (still admissible if fuzz finds it)
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Fund the caller so vm.prank can send transactions if needed
        vm.deal(caller, 1 ether);

        bool ok;
        // attempt the call as the fuzzed caller; capture whether it succeeded
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call succeeded, then c.owner() equals the provided newOwner.
        // This holds for the reference contract for all inputs: only the owner can call setOwner and when it
        // succeeds the owner variable is updated to the supplied address. The mutant may allow non-owners to
        // succeed and thus change owner unexpectedly, so for some inputs this assertion will fail on the mutant.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted/failed, then we assert that owner was not changed to newOwner (defensive check).
            // Read current owner and ensure it's either unchanged or not equal to newOwner.
            assertTrue(c.owner() != newOwner);
        }
    }
}

