pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Forwarder fwd;

    function setUp() public { c = new C(); fwd = new Forwarder(); }

    // fuzzed params: caller (who is the current owner) and newOwner (address to set)
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure caller is the deployed original owner: the deployer in setUp() is address(this) by default,
        // but we want to simulate an arbitrary caller being the owner. So: deploy a fresh instance where `caller` is the deployer.
        // We must follow the rule to use `new C()` in setUp() for `c` per instructions; instead, we will make `caller` the owner
        // by having that address call setOwner on c to set itself as owner first (using prank from the real initial owner).

        // The contract `c` was deployed by this test contract (address(this)) and so address(this) is the initial owner.
        // Let address(this) transfer ownership to `caller` by calling setOwner while pranked as the current owner.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // sanity: this should always succeed on the reference contract; if it doesn't, skip this fuzz case
        vm.assume(ok);

        // Now `caller` is the owner. We will simulate a call chain: caller -> Forwarder -> c.setOwner(newOwner)
        // For the reference contract (checks msg.sender), this forwarded call will fail the onlyOwner check
        // unless the forwarder executes the call as if msg.sender == caller; but a forwarder makes msg.sender == forwarder,
        // so the reference will reject forwarded attempts — only direct calls by `caller` should succeed.
        // The mutant (checking tx.origin) would allow the forwarded call because tx.origin == caller, so the mutant can be changed
        // by the forwarder. Therefore we will compare behavior by performing the forwarded call and then reading c.owner().

        // Fund the forwarder so it can make an external call if needed (not strictly necessary but safe)
        vm.deal(address(fwd), 1 ether);

        // Have the forwarder call c.setOwner(newOwner) but with tx.origin == caller by using vm.prank to make the EOA caller issue the transaction
        vm.prank(caller);
        fwd.callSetOwner(address(c), newOwner);

        // Exactly one assertion: on the correct contract, a forwarded call (originated by caller but using an intermediate contract)
        // must NOT change the owner because onlyOwner uses msg.sender, so msg.sender==forwarder != caller. Thus owner remains caller.
        // The mutant that uses tx.origin would allow the change, making owner == newOwner for some inputs; the fuzzer can find such.
        assertTrue(c.owner() == caller);
    }
}

// Minimal forwarder to create a call chain: EOA (tx.origin) calls this contract, which then calls C.setOwner.
contract Forwarder {
    function callSetOwner(address target, address newOwner) external {
        // forward the call; msg.sender will be this contract, tx.origin will be the EOA that initiated the tx
        (bool s, ) = target.call(abi.encodeWithSignature("setOwner(address)", newOwner));
        require(s);
    }
}

