pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: a candidate new owner address chosen by the fuzzer.
    // General rule: when the current owner calls setOwner(newOwner), after the call c.owner() == newOwner.
    function testFuzz_property(address newOwner) public {
        // keep the fuzzed domain wide but avoid zero-address edge where semantics might be special
        // (we still allow zero if fuzzer picks it; not required to exclude). Optionally bound to avoid msg.sender == address(0) impossible, but not necessary.

        // Ensure the caller is the current owner: setUp deployed c with msg.sender == address(this) (the test contract)
        // So we call directly (no prank) to act as owner.

        // Call setOwner with the fuzzed parameter and capture success via try/catch
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the invariant must hold: c.owner() == newOwner
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, we still assert the property over the public surface by checking that
            // the call did not succeed; this branch preserves the single assertTrue requirement by asserting false
            // only when call erroneously reported success — but to follow the requirement of exactly one assertTrue,
            // we convert this to asserting that ok implies owner==newOwner; implement as a single assertTrue below.
            // (We will not reach here because the single assertTrue is placed after)
        }

        // SINGLE assertion required: the universal property expressed as implication.
        // If the call succeeded (ok == true) then owner() must equal newOwner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

