pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the new owner address. The universal property: when the current owner calls setOwner(newOwner),
    // after a successful call the public owner must equal newOwner.
    // We let the fuzzer supply any address for newOwner (wide domain) and we ensure the caller is the current owner.
    function testFuzz_property(address newOwner) public {
        // keep domain wide: avoid the zero-address only if we believe it's admissible; here we allow any address
        // Make the current test contract the owner by using the owner-setter: c was deployed in setUp by this contract,
        // so address(this) is the owner. We must call as address(this) (default) so no prank is necessary.

        // Call setOwner as the owner with the fuzzed newOwner and capture whether it succeeded.
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded, the contract's public owner must equal the provided parameter.
        // This is a universal property the reference satisfies for all inputs; the mutant that writes owner = address(0)
        // before assigning newOwner can be made to violate observable owner in some scenarios (and the fuzzer will find a failing input).
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, the reference also would revert; we assert that a reverted call implies owner unchanged
            // (owner remains address(this) because setOwner must be callable only by owner and we called as owner)
            assertTrue(c.owner() == address(this));
        }
    }
}

