pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantOwner attacker;

    function setUp() public {
        c = new C();
        // deploy reentrant attacker; it will become owner by being the deployer of this test contract? No—make attacker the owner by transferring ownership via c.setOwner
        attacker = new ReentrantOwner(address(c));
        // make attacker the owner: current owner is this test contract (deployer of C in setUp), so call setOwner to attacker
        // msg.sender must be owner; setUp runs as this contract, which is deployer of C, so valid
        c.setOwner(address(attacker));
        // verify attacker is now owner
        assertEq(c.owner(), address(attacker));
    }

    // fuzz parameter is the newOwner address to set; keep domain wide
    function testFuzz_property(address newOwner) public {
        // wide admissible domain: allow any address (including zero)
        // Let attacker (which is the current owner) call setOwner and re-enter during the call
        // The attacker will attempt to re-enter and perform an observation/interaction that can distinguish an insertion of owner = address(0) before assignment

        // tell attacker which target to set
        attacker.setTarget(newOwner);

        // invoke attacker to call c.setOwner(newOwner) as itself
        attacker.callSetOwner();

        // After the successful call, the general rule: c.owner() == newOwner
        // This is the single assertion: reference C satisfies for all inputs; mutant (which wrote owner = address(0) before setting) can be observed/broken by a reentrant owner.
        assertTrue(c.owner() == newOwner);
    }
}

// Minimal reentrant owner: it is the owner of C and when calling setOwner it re-enters C in its fallback to observe/modify state.
contract ReentrantOwner {
    address public target;
    C public c;

    constructor(address _c) {
        c = C(_c);
    }

    function setTarget(address _t) external {
        target = _t;
    }

    // entry point: call setOwner as this contract (the owner)
    function callSetOwner() external {
        // call C.setOwner from this contract
        c.setOwner(target);
    }

    // fallback invoked if C were to send Ether or call into this contract; also acts as reentrancy during any external calls
    fallback() external payable {
        // perform a read of c.owner() during the external call
        // For the mutant which sets owner = address(0) before assigning, an external observation during the call could see address(0)
        // Do a no-op read to simulate observation; also attempt a harmless reentrant call that does not change final owner but exercises ordering
        address current = c.owner();
        // attempt a benign call that will succeed; use a view via staticcall to avoid state change
        (bool ok, ) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        // silence unused vars
        if (!ok) { revert(); }
    }
}

