// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: the new owner to set (fuzzer supplies addresses)
    function testFuzz_property(address newOwner) public {
        // keep domain wide: disallow zero because owner being zero might be valid but we still allow it
        // No vm.assume to avoid excluding inputs; but ensure newOwner is any address (including zero)

        // Deploy a helper contract that will be the caller and is initially the owner.
        OwnerCaller caller = new OwnerCaller(c);

        // Make the deployed caller the current owner by transferring ownership from the test deployer (who is c's constructor owner)
        // The original deployer (this test contract) is c.owner() now. Let it call setOwner to set caller as owner.
        // As the deployer owner, call setOwner to make caller the owner.
        c.setOwner(address(caller));

        // Now have the caller (which is a contract) call setOwner(newOwner) as the owner.
        // The caller's call will optionally re-enter or observe state; for our property we simply call through.
        bool ok;
        try caller.callSetOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a successful call by the current owner, c.owner() equals the provided newOwner.
        // We assert this single property by reading c.owner() via its public getter.
        // Only assert when the call succeeded (the reference contract never reverts in setOwner when called by owner),
        // so require ok==true to ensure we only check successful executions.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, the reference implementation would only revert when msg.sender != owner,
            // but our caller is the owner so a revert indicates something abnormal — still we must not assert in that case.
            // To keep a single assertion in the test function, we assert a trivially true condition when not ok.
            // However the requirement mandates exactly one assertTrue that reads c; so instead we fail the test by asserting false
            // if the call reverted, because under the reference contract this should not happen.
            assertTrue(false);
        }
    }
}

// Helper contract that will become the owner and call setOwner on c
contract OwnerCaller {
    C c;
    constructor(C _c) {
        c = _c;
    }

    // Called by test to invoke setOwner as this contract (the owner)
    function callSetOwner(address newOwner) external {
        // perform the call as this contract
        c.setOwner(newOwner);
    }
}
